from __future__ import annotations

"""Injectable time source for deterministic token validation.

Token validation compares ``exp``, ``nbf``, and ``iat`` against "now". In a
running service "now" is wall-clock seconds since the epoch, but tests need a
fixed point so a token that is valid for one second is not flaky. Every layer
that needs the current time takes a ``Clock`` instead of calling the wall clock
directly.

Times are integer Unix seconds (UTC) to match the numeric date claims Entra
puts in an access token. A small clock-skew tolerance is applied by the claim
policy, not here; this module only answers "what time is it".
"""

import time


class Clock:
    """A source of the current Unix time in whole seconds."""

    def now(self) -> int:
        return int(time.time())


class FixedClock(Clock):
    """A clock pinned to a fixed instant. Used by tests and replay tooling."""

    def __init__(self, fixed_now: int) -> None:
        if not isinstance(fixed_now, int) or isinstance(fixed_now, bool):
            raise ValueError("fixed_now must be an int")
        if fixed_now < 0:
            raise ValueError("fixed_now must be non-negative")
        self._fixed_now = fixed_now

    def now(self) -> int:
        return self._fixed_now

    def advance(self, seconds: int) -> "FixedClock":
        """Return a new clock moved forward by ``seconds`` (may be negative)."""

        return FixedClock(self._fixed_now + seconds)


class OffsetClock(Clock):
    """Wraps another clock and adds a constant offset.

    Handy for simulating a validating server whose wall clock drifts a few
    seconds from the token issuer. The offset can be negative.
    """

    def __init__(self, base: Clock, offset_seconds: int) -> None:
        if not isinstance(offset_seconds, int) or isinstance(offset_seconds, bool):
            raise ValueError("offset_seconds must be an int")
        self._base = base
        self._offset_seconds = offset_seconds

    def now(self) -> int:
        return self._base.now() + self._offset_seconds


def seconds_until(target: int, clock: Clock) -> int:
    """Positive when ``target`` is in the future relative to ``clock``."""

    return target - clock.now()


def seconds_since(point: int, clock: Clock) -> int:
    """Positive when ``point`` is in the past relative to ``clock``."""

    return clock.now() - point

