from __future__ import annotations

"""Signing-key registry keyed by ``kid``.

Entra publishes a set of signing keys at the tenant JWKS endpoint. Each key has
an id (``kid``), an algorithm it is meant for (``RS256``), and a key type
(``rsa``). When a token arrives, the validator reads the ``kid`` from the header
and looks up the matching key here. A ``kid`` that is not in the store is an
untrusted key the API cannot evaluate.

For this exercise the published keys live in an in-memory store seeded by the
test. Each entry carries the mock key material the crypto backend uses to verify
a signature, plus the algorithm and key type metadata that let the validator
detect algorithm confusion.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class SigningKey:
    """One published signing key.

    ``alg`` is the algorithm this key is intended for, ``key_type`` is the
    family (``rsa`` for asymmetric, ``oct`` for symmetric). ``material`` is the
    secret the mock backend uses to recompute a signature.
    """

    kid: str
    alg: str
    key_type: str
    material: str

    def __post_init__(self) -> None:
        if not self.kid:
            raise ValueError("kid is required")
        if not self.alg:
            raise ValueError("alg is required")
        if self.key_type not in ("rsa", "oct"):
            raise ValueError("key_type must be rsa or oct")
        if not self.material:
            raise ValueError("material is required")


class KeyStore:
    """An in-memory map of ``kid`` to :class:`SigningKey`."""

    def __init__(self) -> None:
        self._keys: dict[str, SigningKey] = {}

    def add(self, key: SigningKey) -> None:
        self._keys[key.kid] = key

    def add_key(self, kid: str, alg: str, key_type: str, material: str) -> SigningKey:
        key = SigningKey(kid=kid, alg=alg, key_type=key_type, material=material)
        self.add(key)
        return key

    def resolve(self, kid: str | None) -> SigningKey | None:
        """Return the key for ``kid`` or ``None`` when it is unknown.

        A ``None`` ``kid`` never resolves: a token must name the key it was
        signed with so the validator can pin verification to a published key.
        """

        if kid is None:
            return None
        return self._keys.get(kid)

    def has(self, kid: str | None) -> bool:
        return self.resolve(kid) is not None

    def known_kids(self) -> list[str]:
        return sorted(self._keys.keys())

    def count(self) -> int:
        return len(self._keys)

