from __future__ import annotations

"""Token structure: header, payload, and the parsing that produces them.

An access token presented to the API is three base64url segments joined by
dots: ``header.payload.signature``. The header carries the signing metadata
(``alg``, ``kid``, ``typ``); the payload carries the claims the API trusts the
issuer to assert (``iss``, ``aud``, ``exp``, ``nbf``, ``iat``, ``tid``, and the
caller's granted scopes or app roles). The signature covers ``header.payload``.

This module is pure structure. It decodes the segments, validates that the
shapes are well formed, and exposes typed views. It makes no trust decisions:
whether the signature is good, whether the audience is ours, and whether the
token is within its validity window all live in the policy and validator
layers. Keeping decode separate from trust means a malformed token is rejected
with a parse error, while a well-formed but untrusted token is rejected with a
policy reason.
"""

import base64
import json
from dataclasses import dataclass, field


class TokenParseError(Exception):
    """Raised when a token is not three well-formed base64url JSON segments."""


def _b64url_decode(segment: str) -> bytes:
    if not isinstance(segment, str) or segment == "":
        raise TokenParseError("empty token segment")
    padding = "=" * (-len(segment) % 4)
    try:
        return base64.urlsafe_b64decode(segment + padding)
    except (ValueError, TypeError) as exc:
        raise TokenParseError(f"segment is not valid base64url: {exc}") from exc


def _b64url_encode(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _decode_json_segment(segment: str, label: str) -> dict:
    raw = _b64url_decode(segment)
    try:
        parsed = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise TokenParseError(f"{label} segment is not JSON: {exc}") from exc
    if not isinstance(parsed, dict):
        raise TokenParseError(f"{label} segment must be a JSON object")
    return parsed


@dataclass(frozen=True)
class TokenHeader:
    """The decoded JOSE header.

    ``alg`` is the declared signing algorithm, ``kid`` selects the signing key,
    ``typ`` should be ``JWT`` for an access token. Unknown extra fields are kept
    so the raw header round-trips for signature checks.
    """

    alg: str
    kid: str | None
    typ: str | None
    raw: dict = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not isinstance(self.alg, str) or not self.alg.strip():
            raise TokenParseError("header.alg is required")


@dataclass(frozen=True)
class TokenClaims:
    """The decoded payload claims the API consumes.

    ``scp`` is a space-delimited string of delegated scopes; ``roles`` is a list
    of application roles. A token may carry either or both. Numeric date claims
    are whole Unix seconds.
    """

    iss: str | None
    aud: object
    exp: int | None
    nbf: int | None
    iat: int | None
    tid: str | None
    scp: str | None
    roles: tuple[str, ...]
    sub: str | None
    raw: dict = field(default_factory=dict)

    def scope_list(self) -> list[str]:
        if not self.scp:
            return []
        return [part for part in self.scp.split(" ") if part]

    def role_list(self) -> list[str]:
        return list(self.roles)

    def granted_permissions(self) -> list[str]:
        """All scopes and roles, in a stable order, deduplicated."""

        seen: list[str] = []
        for item in self.scope_list() + self.role_list():
            if item not in seen:
                seen.append(item)
        return seen


@dataclass(frozen=True)
class DecodedToken:
    """A structurally valid token, not yet trusted.

    ``signing_input`` is the exact ``header.payload`` string the signature must
    cover. ``signature`` is the third segment as presented.
    """

    header: TokenHeader
    claims: TokenClaims
    signing_input: str
    signature: str
    header_segment: str
    payload_segment: str

    def kid(self) -> str | None:
        return self.header.kid

    def alg(self) -> str:
        return self.header.alg


def _coerce_int(value: object, label: str) -> int | None:
    if value is None:
        return None
    if isinstance(value, bool):
        raise TokenParseError(f"{label} must be a number, not a bool")
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    raise TokenParseError(f"{label} must be an integer number of seconds")


def _coerce_roles(value: object) -> tuple[str, ...]:
    if value is None:
        return ()
    if isinstance(value, str):
        return (value,) if value else ()
    if isinstance(value, (list, tuple)):
        roles = []
        for item in value:
            if not isinstance(item, str):
                raise TokenParseError("roles entries must be strings")
            if item:
                roles.append(item)
        return tuple(roles)
    raise TokenParseError("roles must be a string or list of strings")


def parse_header(segment: str) -> TokenHeader:
    raw = _decode_json_segment(segment, "header")
    return TokenHeader(
        alg=raw.get("alg") if isinstance(raw.get("alg"), str) else (raw.get("alg") or ""),
        kid=raw.get("kid"),
        typ=raw.get("typ"),
        raw=raw,
    )


def parse_claims(segment: str) -> TokenClaims:
    raw = _decode_json_segment(segment, "payload")
    return TokenClaims(
        iss=raw.get("iss"),
        aud=raw.get("aud"),
        exp=_coerce_int(raw.get("exp"), "exp"),
        nbf=_coerce_int(raw.get("nbf"), "nbf"),
        iat=_coerce_int(raw.get("iat"), "iat"),
        tid=raw.get("tid"),
        scp=raw.get("scp") if isinstance(raw.get("scp"), str) else None,
        roles=_coerce_roles(raw.get("roles")),
        sub=raw.get("sub"),
        raw=raw,
    )


def decode_token(token: str) -> DecodedToken:
    """Split and decode a compact token into header, claims, and signature.

    Raises ``TokenParseError`` for anything that is not three well-formed
    segments. Does not check the signature or any claim value.
    """

    if not isinstance(token, str) or not token.strip():
        raise TokenParseError("token must be a non-empty string")
    segments = token.split(".")
    if len(segments) != 3:
        raise TokenParseError("token must have exactly three segments")
    header_segment, payload_segment, signature = segments
    header = parse_header(header_segment)
    claims = parse_claims(payload_segment)
    return DecodedToken(
        header=header,
        claims=claims,
        signing_input=f"{header_segment}.{payload_segment}",
        signature=signature,
        header_segment=header_segment,
        payload_segment=payload_segment,
    )


def encode_segment(payload: dict) -> str:
    """Encode a JSON object to a base64url segment. Used by token minting."""

    raw = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return _b64url_encode(raw)

